WITH lines AS (SELECT id, host, log_ts, level, latency_ms, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, v) SELECT id, host, log_ts, level, latency_ms, status_code, attr_key, v, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level), 4) AS status_code_share, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY host), 4) AS latency_ms_share, MAX(latency_ms) OVER (PARTITION BY attr_key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS latency_ms_max_2h, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level), 4) AS latency_ms_share_2 FROM lines
